"""Order pricing, exact to the penny (integer pennies, halves round up)."""

import datetime
from dataclasses import dataclass
from decimal import Decimal
from typing import Dict, List, Optional

from .parsing import TAX_RATES, Order, Product


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal
    order: str = ""
    date: Optional[datetime.date] = None
    customer: str = ""


def money(pennies: int) -> Decimal:
    """Exact two-decimal Decimal for an integer number of pennies."""
    sign = "-" if pennies < 0 else ""
    whole, frac = divmod(abs(pennies), 100)
    return Decimal("%s%d.%02d" % (sign, whole, frac))


def to_pennies(amount: Decimal) -> int:
    sign, digits, exponent = amount.as_tuple()
    value = int("".join(map(str, digits)) or "0")
    shift = exponent + 2
    if shift >= 0:
        value *= 10 ** shift
    else:
        value = _div_half_up(value, 10 ** (-shift))
    return -value if sign else value


def _div_half_up(numerator: int, denominator: int) -> int:
    """numerator / denominator rounded half up (numerator >= 0)."""
    return (2 * numerator + denominator) // (2 * denominator)


def price_order(order: Order, catalog: Dict[str, Product]) -> Quote:
    rows = []  # (sku, qty, unit_p, gross_p, discount_p, net_p, tax rate %)
    for sku, quantity in order.lines:
        product = catalog[sku]
        unit = to_pennies(product.price)
        gross = unit * quantity
        percent = 10 if quantity >= 50 else 5 if quantity >= 10 else 0
        discount = _div_half_up(gross * percent, 100)
        rows.append((sku, quantity, unit, gross, -discount, gross - discount, TAX_RATES[product.tax]))

    subtotal = sum(r[5] for r in rows)
    order_discount = _div_half_up(subtotal * 3, 100) if subtotal >= 50000 else 0

    # Share the order discount over the lines: floor each share, then hand the
    # leftover pennies to the biggest lost fractions (earlier line wins ties).
    shares = [order_discount * r[5] // subtotal if subtotal else 0 for r in rows]
    lost = [order_discount * r[5] % subtotal if subtotal else 0 for r in rows]
    leftover = order_discount - sum(shares)
    for index in sorted(range(len(rows)), key=lambda i: (-lost[i], i))[:leftover]:
        shares[index] += 1

    tax = 0
    for row, share in zip(rows, shares):
        tax += _div_half_up((row[5] - share) * row[6], 100)

    lines = [QuoteLine(r[0], r[1], money(r[2]), money(r[3]), money(r[4]), money(r[5])) for r in rows]
    return Quote(
        lines=lines,
        subtotal=money(subtotal),
        order_discount=money(-order_discount),
        tax=money(tax),
        total=money(subtotal - order_discount + tax),
        order=order.id,
        date=order.date,
        customer=order.customer,
    )
EOF
cat > src/stockroom/shelves.py <<'EOF'
"""Stock levels, status, low-stock list and history."""

from typing import Dict, List, Sequence

from .parsing import Movement, Product


def stock_levels(catalog: Dict[str, Product], movements: Sequence[Movement]) -> Dict[str, int]:
    levels = {sku: 0 for sku in sorted(catalog)}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def status(onhand: int, reorder: int) -> str:
    if onhand == 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    return max(1, 2 * reorder - onhand)


def counting_order(movements: Sequence[Movement]) -> List[Movement]:
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda mv: mv.date)


def history(sku: str, movements: Sequence[Movement]) -> List[tuple]:
    """(movement, balance after it) for one SKU, in counting order."""
    rows = []
    balance = 0
    for move in counting_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows
EOF
cat > src/stockroom/orders.py <<'EOF'
"""Shipping, status and the report for orders."""

import datetime
from typing import Dict, List, Sequence, Tuple

from .parsing import Movement, Order, Product
from .pricing import Quote, price_order
from .shelves import counting_order


def order_note(order: Order) -> str:
    return "order " + order.id


def shipped_so_far(order: Order, movements: Sequence[Movement]) -> List[int]:
    """Units shipped per order line (capped at the quantity ordered)."""
    note = order_note(order)
    sent = {}  # type: Dict[str, int]
    for move in movements:
        if move.quantity < 0 and move.note == note:
            sent[move.sku] = sent.get(move.sku, 0) - move.quantity
    return [min(quantity, sent.get(sku, 0)) for sku, quantity in order.lines]


def available_on(sku: str, date: datetime.date, movements: Sequence[Movement]) -> int:
    """Most that can leave the shelf on DATE without any later movement going below zero."""
    level = 0
    lowest_later = None
    for move in counting_order(movements):
        if move.sku != sku:
            continue
        level += move.quantity
        if move.date > date:
            if lowest_later is None or level < lowest_later:
                lowest_later = level
        else:
            on_date = level
    else:
        on_date = level if lowest_later is None else on_date_value(sku, date, movements)
    return max(0, min(on_date, lowest_later) if lowest_later is not None else max(0, on_date))


def on_date_value(sku: str, date: datetime.date, movements: Sequence[Movement]) -> int:
    return sum(m.quantity for m in movements if m.sku == sku and m.date <= date)


def order_status(order: Order, shipped: Sequence[int]) -> str:
    if all(sent >= qty for (_, qty), sent in zip(order.lines, shipped)):
        return "complete"
    if not any(shipped):
        return "open"
    return "partial"


def shipped_order(order: Order, shipped: Sequence[int]) -> Order:
    """An order made of the shipped quantities only (lines with nothing shipped left out)."""
    lines = [(sku, sent) for (sku, _), sent in zip(order.lines, shipped) if sent > 0]
    return Order(order.id, order.date, order.customer, lines, order.line)


def sort_key(order: Order) -> Tuple[datetime.date, int, str]:
    return (order.date, int(order.id[3:]), order.id)


def report_rows(
    orders: Sequence[Order], catalog: Dict[str, Product], movements: Sequence[Movement]
) -> List[dict]:
    rows = []
    for order in sorted(orders, key=sort_key):
        shipped = shipped_so_far(order, movements)
        quoted = price_order(order, catalog)  # type: Quote
        if any(shipped):
            invoiced = price_order(shipped_order(order, shipped), catalog).total
        else:
            invoiced = quoted.total * 0
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": order_status(order, shipped),
                "ordered": sum(q for _, q in order.lines),
                "shipped": sum(shipped),
                "quoted": quoted.total,
                "invoiced": invoiced,
            }
        )
    return rows
EOF

