        sku_text, name, price_text, reorder_text = fields[:4]
        sku = normalise_sku(sku_text)
        if sku is None:
            raise ParseError("bad SKU %r" % sku_text, number)
        if sku in catalog:
            raise ParseError("duplicate SKU %s" % sku, number)
        if not name:
            raise ParseError("empty name", number)
        m = PRICE_RE.fullmatch(price_text)
        if not m:
            raise ParseError("bad price %r" % price_text, number)
        price = Decimal("%s.%s" % (m.group(1), (m.group(2) or "").ljust(2, "0")))
        if price < Decimal("0.01"):
            raise ParseError("price must be at least 0.01", number)
        if not UINT_RE.fullmatch(reorder_text):
            raise ParseError("bad reorder level %r" % reorder_text, number)
        tax = "standard"
        if len(fields) == 5:
            tax_text = fields[4]
            tax = tax_text.lower() if tax_text.isascii() else ""
            if tax not in TAX_RATES:
                raise ParseError("bad tax %r (expected standard, reduced or zero)" % tax_text, number)
