                raise ParseError("bad quantity %r" % pair[1], number)
            quantity = _to_int(pair[1], number, "quantity")
            if quantity < 1:
                raise ParseError("quantity must be at least 1", number)
            used.add(sku)
            lines.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, number))
    return orders
