"""Order pricing, exact to the penny (integer pennies, halves round up)."""

import datetime
from dataclasses import dataclass
from decimal import Decimal
from typing import Dict, List, Optional

from .parsing import TAX_RATES, Order, Product


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal
    order: str = ""
    date: Optional[datetime.date] = None
    customer: str = ""


def money(pennies: int) -> Decimal:
    """Exact two-decimal Decimal for an integer number of pennies."""
    sign = "-" if pennies < 0 else ""
    whole, frac = divmod(abs(pennies), 100)
    return Decimal("%s%d.%02d" % (sign, whole, frac))


def to_pennies(amount: Decimal) -> int:
    sign, digits, exponent = amount.as_tuple()
    value = int("".join(map(str, digits)) or "0")
    shift = exponent + 2
    if shift >= 0:
        value *= 10 ** shift
    else:
        value = _div_half_up(value, 10 ** (-shift))
    return -value if sign else value


def _div_half_up(numerator: int, denominator: int) -> int:
    """numerator / denominator rounded half up (numerator >= 0)."""
    return (2 * numerator + denominator) // (2 * denominator)


def price_order(order: Order, catalog: Dict[str, Product]) -> Quote:
    rows = []  # (sku, qty, unit_p, gross_p, discount_p, net_p, tax rate %)
    for sku, quantity in order.lines:
        product = catalog[sku]
        unit = to_pennies(product.price)
        gross = unit * quantity
        percent = 10 if quantity >= 50 else 5 if quantity >= 10 else 0
        discount = _div_half_up(gross * percent, 100)
        rows.append((sku, quantity, unit, gross, -discount, gross - discount, TAX_RATES[product.tax]))

    subtotal = sum(r[5] for r in rows)
    order_discount = _div_half_up(subtotal * 3, 100) if subtotal >= 50000 else 0

    # Share the order discount over the lines: floor each share, then hand the
    # leftover pennies to the biggest lost fractions (earlier line wins ties).
    shares = [order_discount * r[5] // subtotal if subtotal else 0 for r in rows]
    lost = [order_discount * r[5] % subtotal if subtotal else 0 for r in rows]
    leftover = order_discount - sum(shares)
    for index in sorted(range(len(rows)), key=lambda i: (-lost[i], i))[:leftover]:
        shares[index] += 1

    tax = 0
    for row, share in zip(rows, shares):
        tax += _div_half_up((row[5] - share) * row[6], 100)

    lines = [QuoteLine(r[0], r[1], money(r[2]), money(r[3]), money(r[4]), money(r[5])) for r in rows]
    return Quote(
        lines=lines,
        subtotal=money(subtotal),
        order_discount=money(-order_discount),
        tax=money(tax),
        total=money(subtotal - order_discount + tax),
        order=order.id,
        date=order.date,
        customer=order.customer,
    )
