    for index in sorted(range(len(rows)), key=lambda i: (-lost[i], i))[:leftover]:
        shares[index] += 1

    tax = 0
    for row, share in zip(rows, shares):
        tax += _div_half_up((row[5] - share) * row[6], 100)

    lines = [QuoteLine(r[0], r[1], money(r[2]), money(r[3]), money(r[4]), money(r[5])) for r in rows]
    return Quote(
        lines=lines,
        subtotal=money(subtotal),
        order_discount=money(-order_discount),
        tax=money(tax),
        total=money(subtotal - order_discount + tax),
        order=order.id,
        date=order.date,
        customer=order.customer,
    )
