"""Stock levels, status, low-stock list and history."""

from typing import Dict, List, Sequence

from .parsing import Movement, Product


def stock_levels(catalog: Dict[str, Product], movements: Sequence[Movement]) -> Dict[str, int]:
    levels = {sku: 0 for sku in sorted(catalog)}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def status(onhand: int, reorder: int) -> str:
    if onhand == 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    return max(1, 2 * reorder - onhand)


def counting_order(movements: Sequence[Movement]) -> List[Movement]:
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda mv: mv.date)


def history(sku: str, movements: Sequence[Movement]) -> List[tuple]:
    """(movement, balance after it) for one SKU, in counting order."""
    rows = []
    balance = 0
    for move in counting_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows
