def cmd_stock(request: Request, data: Data) -> str:
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        rows.append((sku, product.name, levels[sku], status(levels[sku], product.reorder)))
    if request.json:
        return dump_json([{"sku": s, "name": n, "onhand": q, "status": st} for s, n, q, st in rows])
    return lines_out(["%s %d %s %s" % (s, q, st, n) for s, n, q, st in rows])


def cmd_low(request: Request, data: Data) -> str:
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        if status(levels[sku], product.reorder) != "ok":
            rows.append((sku, levels[sku], product.reorder, buy_quantity(levels[sku], product.reorder)))
    if request.json:
        return dump_json([{"sku": s, "onhand": q, "reorder": r, "buy": b} for s, q, r, b in rows])
    return lines_out(["%s %d %d %d" % row for row in rows])


def cmd_history(request: Request, data: Data) -> str:
    sku = normalise_sku(request.args[0])
    if sku is None or sku not in data.catalog:
        raise CliError(1, "unknown SKU %s" % request.args[0])
    rows = [("%s" % m.date.isoformat(), "%+d" % m.quantity, balance, m.note) for m, balance in history(sku, data.movements)]
    if request.json:
        return dump_json([{"date": d, "delta": dl, "balance": b, "note": n} for d, dl, b, n in rows])
    return lines_out(["%s %s %d%s" % (d, dl, b, " " + n if n else "") for d, dl, b, n in rows])


def movement_line(move: Movement) -> str:
    return "%s %s %+d%s" % (move.date.isoformat(), move.sku, move.quantity, " " + move.note if move.note else "")


def append_movements(data: Data, new: Sequence[Movement]) -> None:
    """Validate the movements against the file, then append them (all or nothing)."""
    text = "".join(movement_line(m) + "\n" for m in new)
