    sku = normalise_sku(sku_text)
    if sku is None or sku not in data.catalog:
        raise CliError(1, "unknown SKU %s" % sku_text)
    if not (qty_text.isascii() and qty_text.isdigit()) or int(qty_text) < 1:
        raise CliError(1, "bad quantity %r (expected a whole number of one or more)" % qty_text)
    if "\n" in note or "\r" in note:
