    raise CliError(1, "unknown order %s" % text)


def format_quote(quote: Quote, prefix: str = "") -> str:
    lines = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    for line in quote.lines:
        lines.append("%s %d %s %s %s %s" % (line.sku, line.quantity, line.unit, line.gross, line.discount, line.net))
    lines.append("subtotal %s" % quote.subtotal)
    lines.append("order discount %s" % quote.order_discount)
    lines.append("tax %s" % quote.tax)
    lines.append("total %s" % quote.total)
    return lines_out(lines)


def quote_json(quote: Quote) -> str:
    return dump_json(
