    return quote_json(quote) if request.json else format_quote(quote)


def cmd_invoice(request: Request, data: Data) -> str:
    order = find_order(data, request.args[0])
    shipped = shipped_so_far(order, data.movements)
    if not any(shipped):
        raise CliError(1, "nothing has shipped for %s" % order.id)
    quote = price_order(shipped_order(order, shipped), data.catalog)
    return quote_json(quote) if request.json else format_quote(quote, "invoice ")


def cmd_fulfil(request: Request, data: Data) -> str:
    order = find_order(data, request.args[0])
    date = parse_date(request.args[1])
    if date < order.date:
        raise CliError(1, "%s: cannot fulfil on %s, before the order date %s" % (order.id, date.isoformat(), order.date.isoformat()))
    before = shipped_so_far(order, data.movements)
    new = []  # type: List[Movement]
    after = []
    out = []
    line_no = next_line_number(data)
    for (sku, quantity), sent in zip(order.lines, before):
        owed = quantity - sent
        ship = min(owed, available_on(sku, date, data.movements))
        if ship > 0:
            new.append(Movement(date, sku, -ship, "order " + order.id, line_no + len(new)))
        after.append(sent + ship)
        out.append("%s shipped %d backordered %d" % (sku, ship, owed - ship))
    out.append("status %s" % order_status(order, after))
    if new:
        append_movements(data, new)
    return lines_out(out)


def cmd_report(request: Request, data: Data) -> str:
    rows = report_rows(data.orders, data.catalog, data.movements)
    keys = ("order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced")
    if request.format == "json":
        return dump_json([{k: (str(r[k]) if k in ("quoted", "invoiced") else r[k]) for k in keys} for r in rows])
    if request.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(keys)
        for r in rows:
            writer.writerow([r[k] for k in keys])
        return buffer.getvalue()
    return lines_out(
        ["%s %s %s %s %d/%d %s %s" % (r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"]) for r in rows]
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}  # type: Dict[str, Callable[[Request, Data], str]]


def run(argv: Sequence[str]) -> str:
    request = parse_command_line(argv)
    data = Data(request)
    return HANDLERS[request.command](request, data)


def _utf8(stream) -> None:
    reconfigure = getattr(stream, "reconfigure", None)
    if reconfigure is not None:
        try:
            reconfigure(encoding="utf-8", errors="replace", newline="\n")
        except (ValueError, OSError):
            pass


def _silence_stdout() -> None:
    """Point stdout at the null device so the interpreter's exit flush stays quiet."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass


def main(argv: Optional[Sequence[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    _utf8(sys.stdout)
    _utf8(sys.stderr)
    try:
        output = run(argv)
    except CliError as exc:
        try:
            sys.stderr.write("stockroom: %s\n" % exc.message)
            sys.stderr.flush()
        except (OSError, ValueError):
            pass
        return exc.code
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
    return 0
