def parse_command_line(argv: Sequence[str]) -> Request:
    request = Request()
    rest = []  # type: List[str]
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise CliError(2, "option --dir needs a value")
            request.directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            request.directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    if not rest:
        raise CliError(2, "no command given")
    command = rest[0]
    if command.startswith("-"):
        raise CliError(2, "unknown option %s" % command)
    if command not in COMMANDS:
        raise CliError(2, "unknown command %s" % command)
    request.command = command
    low, high, flags, _ = COMMANDS[command]
    tokens = rest[1:]
    if command in FREE_FORM:
        request.args = tokens
    else:
        j = 0
        while j < len(tokens):
            token = tokens[j]
            if token == "--json" and "--json" in flags:
                request.json = True
            elif token == "--format" or token.startswith("--format="):
                if "--format" not in flags:
                    raise CliError(2, "unknown option %s" % token.split("=")[0])
                if token == "--format":
                    if j + 1 >= len(tokens):
                        raise CliError(2, "option --format needs a value")
                    j += 1
                    value = tokens[j]
                else:
                    value = token[len("--format="):]
                if value not in ("text", "csv", "json"):
                    raise CliError(2, "bad --format value %r (expected text, csv or json)" % value)
                request.format = value
            elif token.startswith("-"):
                raise CliError(2, "unknown option %s" % token)
            else:
                request.args.append(token)
            j += 1
    if not low <= len(request.args) <= high:
        raise CliError(2, "wrong number of arguments for %s" % command)
    if command in ("receive", "ship") and parse_date(request.args[0]) is None:
        raise CliError(2, "bad date %r (expected YYYY-MM-DD)" % request.args[0])
    if command == "fulfil" and parse_date(request.args[1]) is None:
        raise CliError(2, "bad date %r (expected YYYY-MM-DD)" % request.args[1])
    return request


def read_file(directory: str, name: str, required: bool) -> Tuple[str, bytes]:
    """Text and raw bytes of a data file ('' when an optional file is missing)."""
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        if required:
            raise CliError(2, "%s: file not found" % name) from None
        return "", b""
    except OSError as exc:
        raise CliError(2, "%s: cannot read (%s)" % (name, exc.strerror or exc)) from None
    try:
        return raw.decode("utf-8"), raw
    except UnicodeDecodeError:
        raise CliError(2, "%s: not valid UTF-8" % name) from None


def _parsed(name: str, parse: Callable, *args):
    try:
        return parse(*args)
    except ParseError as exc:
        raise CliError(1, "%s: %s" % (name, exc)) from None


class Data:
    """The files a command reads, loaded in the order catalogue, movements, orders."""

    def __init__(self, request: Request) -> None:
        directory = request.directory
        if not os.path.isdir(directory):
            raise CliError(2, "%s: folder not found" % directory)
        wanted = COMMANDS[request.command][3]
        text, _ = read_file(directory, CATALOG, True)
        self.catalog = _parsed(CATALOG, parse_catalog, text)
        self.movements = []  # type: List[Movement]
        self.movements_raw = b""
        self.orders = []
        if MOVEMENTS in wanted:
            text, self.movements_raw = read_file(directory, MOVEMENTS, False)
            self.movements = _parsed(MOVEMENTS, parse_movements, text, self.catalog)
        if ORDERS in wanted:
            text, _ = read_file(directory, ORDERS, False)
            self.orders = _parsed(ORDERS, parse_orders, text, self.catalog)
        self.movements_path = os.path.join(directory, MOVEMENTS)


def dump_json(obj) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines: Sequence[str]) -> str:
    return "".join(line + "\n" for line in lines)


# ---------------------------------------------------------------- shelves

def cmd_stock(request: Request, data: Data) -> str:
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        rows.append((sku, product.name, levels[sku], status(levels[sku], product.reorder)))
    if request.json:
        return dump_json([{"sku": s, "name": n, "onhand": q, "status": st} for s, n, q, st in rows])
    return lines_out(["%s %d %s %s" % (s, q, st, n) for s, n, q, st in rows])


def cmd_low(request: Request, data: Data) -> str:
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        if status(levels[sku], product.reorder) != "ok":
            rows.append((sku, levels[sku], product.reorder, buy_quantity(levels[sku], product.reorder)))
    if request.json:
        return dump_json([{"sku": s, "onhand": q, "reorder": r, "buy": b} for s, q, r, b in rows])
    return lines_out(["%s %d %d %d" % row for row in rows])


def cmd_history(request: Request, data: Data) -> str:
    sku = normalise_sku(request.args[0])
    if sku is None or sku not in data.catalog:
        raise CliError(1, "unknown SKU %s" % request.args[0])
    rows = [("%s" % m.date.isoformat(), "%+d" % m.quantity, balance, m.note) for m, balance in history(sku, data.movements)]
    if request.json:
        return dump_json([{"date": d, "delta": dl, "balance": b, "note": n} for d, dl, b, n in rows])
    return lines_out(["%s %s %d%s" % (d, dl, b, " " + n if n else "") for d, dl, b, n in rows])


def movement_line(move: Movement) -> str:
    return "%s %s %+d%s" % (move.date.isoformat(), move.sku, move.quantity, " " + move.note if move.note else "")


def append_movements(data: Data, new: Sequence[Movement]) -> None:
    """Validate the movements against the file, then append them (all or nothing)."""
    text = "".join(movement_line(m) + "\n" for m in new)
    try:
        payload = text.encode("utf-8")
    except UnicodeEncodeError:
        raise CliError(1, "note cannot be written as UTF-8") from None
    try:
        validate_movements(list(data.movements) + list(new))
    except ParseError as exc:
        raise CliError(1, "%s: %s" % (MOVEMENTS, exc)) from None
    if data.movements_raw and not data.movements_raw.endswith(b"\n"):
        payload = b"\n" + payload
    try:
        with open(data.movements_path, "ab") as handle:
            handle.write(payload)
    except OSError as exc:
        raise CliError(2, "%s: cannot write (%s)" % (MOVEMENTS, exc.strerror or exc)) from None


def next_line_number(data: Data) -> int:
    raw = data.movements_raw
    count = raw.count(b"\n")
    return count + 1 if not raw or raw.endswith(b"\n") else count + 2


def cmd_move(request: Request, data: Data) -> str:
    date_text, sku_text, qty_text = request.args[:3]
    note = request.args[3].strip(WS) if len(request.args) > 3 else ""
    sku = normalise_sku(sku_text)
    if sku is None or sku not in data.catalog:
        raise CliError(1, "unknown SKU %s" % sku_text)
    if not (qty_text.isascii() and qty_text.isdigit()) or int(qty_text) < 1:
        raise CliError(1, "bad quantity %r (expected a whole number of one or more)" % qty_text)
    if "\n" in note or "\r" in note:
        raise CliError(1, "a note may not contain a line break")
    quantity = int(qty_text) * (1 if request.command == "receive" else -1)
    move = Movement(parse_date(date_text), sku, quantity, note, next_line_number(data))
    append_movements(data, [move])
    return movement_line(move) + "\n"


# ----------------------------------------------------------------- orders

def find_order(data: Data, text: str):
    order_id = normalise_order_id(text)
    for order in data.orders:
        if order.id == order_id:
            return order
    raise CliError(1, "unknown order %s" % text)


def format_quote(quote: Quote, prefix: str = "") -> str:
    lines = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    for line in quote.lines:
        lines.append("%s %d %s %s %s %s" % (line.sku, line.quantity, line.unit, line.gross, line.discount, line.net))
    lines.append("subtotal %s" % quote.subtotal)
    lines.append("order discount %s" % quote.order_discount)
    lines.append("tax %s" % quote.tax)
    lines.append("total %s" % quote.total)
    return lines_out(lines)


def quote_json(quote: Quote) -> str:
    return dump_json(
        {
            "order": quote.order,
            "date": quote.date.isoformat(),
            "customer": quote.customer,
            "lines": [
                {
                    "sku": l.sku,
                    "quantity": l.quantity,
                    "unit": str(l.unit),
                    "gross": str(l.gross),
                    "discount": str(l.discount),
                    "net": str(l.net),
                }
                for l in quote.lines
            ],
            "subtotal": str(quote.subtotal),
            "order_discount": str(quote.order_discount),
            "tax": str(quote.tax),
            "total": str(quote.total),
        }
    )


def cmd_quote(request: Request, data: Data) -> str:
    quote = price_order(find_order(data, request.args[0]), data.catalog)
    return quote_json(quote) if request.json else format_quote(quote)


def cmd_invoice(request: Request, data: Data) -> str:
    order = find_order(data, request.args[0])
    shipped = shipped_so_far(order, data.movements)
    if not any(shipped):
        raise CliError(1, "nothing has shipped for %s" % order.id)
    quote = price_order(shipped_order(order, shipped), data.catalog)
    return quote_json(quote) if request.json else format_quote(quote, "invoice ")


def cmd_fulfil(request: Request, data: Data) -> str:
    order = find_order(data, request.args[0])
    date = parse_date(request.args[1])
    if date < order.date:
        raise CliError(1, "%s: cannot fulfil on %s, before the order date %s" % (order.id, date.isoformat(), order.date.isoformat()))
    before = shipped_so_far(order, data.movements)
    new = []  # type: List[Movement]
    after = []
    out = []
    line_no = next_line_number(data)
    for (sku, quantity), sent in zip(order.lines, before):
        owed = quantity - sent
        ship = min(owed, available_on(sku, date, data.movements))
        if ship > 0:
            new.append(Movement(date, sku, -ship, "order " + order.id, line_no + len(new)))
        after.append(sent + ship)
        out.append("%s shipped %d backordered %d" % (sku, ship, owed - ship))
    out.append("status %s" % order_status(order, after))
    if new:
        append_movements(data, new)
    return lines_out(out)


def cmd_report(request: Request, data: Data) -> str:
    rows = report_rows(data.orders, data.catalog, data.movements)
    keys = ("order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced")
    if request.format == "json":
        return dump_json([{k: (str(r[k]) if k in ("quoted", "invoiced") else r[k]) for k in keys} for r in rows])
    if request.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(keys)
        for r in rows:
            writer.writerow([r[k] for k in keys])
        return buffer.getvalue()
    return lines_out(
        ["%s %s %s %s %d/%d %s %s" % (r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"]) for r in rows]
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}  # type: Dict[str, Callable[[Request, Data], str]]


def run(argv: Sequence[str]) -> str:
    request = parse_command_line(argv)
    data = Data(request)
    return HANDLERS[request.command](request, data)


def _utf8(stream) -> None:
    reconfigure = getattr(stream, "reconfigure", None)
    if reconfigure is not None:
        try:
            reconfigure(encoding="utf-8", errors="replace", newline="\n")
        except (ValueError, OSError):
            pass


def _silence_stdout() -> None:
    """Point stdout at the null device so the interpreter's exit flush stays quiet."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass


def main(argv: Optional[Sequence[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    _utf8(sys.stdout)
    _utf8(sys.stderr)
    try:
        output = run(argv)
    except CliError as exc:
        try:
            sys.stderr.write("stockroom: %s\n" % exc.message)
            sys.stderr.flush()
        except (OSError, ValueError):
            pass
        return exc.code
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
    return 0
